def atom_stats(tree):
    """Return ``(atom occurrences, path-service occurrences, complex)``."""
    atoms = 0
    symbols = 0
    complex_rule = not (tree[0] == 'atom' and tree[1] == 'match')
    for _op, path in iter_atoms(tree):
        atoms += 1
        symbols += len(path)
    return atoms, symbols, complex_rule


def parse_policy(text):
    """Parse one policy string.

    Returns ``(rules, atom_occurrences, path_service_occurrences)`` where every
    rule is a ``(predicate_tree, allow_flag)`` pair, or raises ``PolicyError``.
    """
    reader = _Reader(_tokens(text))
    rules = []
    atoms = 0
    symbols = 0
    complex_rules = 0
    nonmatch = set()
    while reader.live:
        tree = _pred(reader, 0)
        action = reader.take()
        if action == 'allow':
            flag = True
        elif action == 'drop':
            flag = False
        else:
            raise PolicyError('action')
        if reader.take() != ';':
            raise PolicyError('rule terminator')
        count, pathlen, complex_rule = atom_stats(tree)
        for op, path in iter_atoms(tree):
            if op != 'match' and len(path) > MAX_NONMATCH_PATH:
                raise PolicyError('non-match path length')
        if complex_rule:
            complex_rules += 1
            if count > MAX_COMPLEX_ATOMS:
                raise PolicyError('expression atom bound')
        if nonmatch_add(tree, nonmatch) > MAX_NONMATCH_DISTINCT:
            raise PolicyError('distinct non-match atom bound')
        atoms += count
        symbols += pathlen
        if atoms > MAX_ATOMS or symbols > MAX_PATHSYM:
            raise PolicyError('string atom bound')
        rules.append((tree, flag))
    if complex_rules > MAX_COMPLEX_RULES:
        raise PolicyError('complex rule bound')
    if len(nonmatch) > MAX_NONMATCH_DISTINCT:
        raise PolicyError('distinct non-match atom bound')
    return rules, atoms, symbols


def nonmatch_add(tree, seen):
    for op, path in iter_atoms(tree):
        if op != 'match':
            seen.add((op, path))
    return len(seen)
